import "node:module";
import node_path from "node:path";
import { color as logger_color, logger as logger_logger, isTTY } from "./d~0.js";
const GLOB_REGEX = /[*?{}[\]()!@+|]/;
const isGlob = (str)=>GLOB_REGEX.test(str);
async function createChokidar(pathOrGlobs, root, options) {
    const chokidar = await import("./chokidar~0.js");
    const watchFiles = new Set();
    const globPatterns = pathOrGlobs.filter((pathOrGlob)=>{
        if (isGlob(pathOrGlob)) return true;
        watchFiles.add(pathOrGlob);
        return false;
    });
    if (globPatterns.length) {
        const { glob } = await import("./zb~0.js");
        const files = await glob(globPatterns, {
            cwd: root,
            absolute: true
        });
        for (const file of files)watchFiles.add(file);
    }
    const watcher = chokidar.watch(Array.from(watchFiles), options);
    if (watchFiles.size > 0) await new Promise((resolve)=>watcher.once('ready', ()=>resolve()));
    return watcher;
}
async function watchFilesForRestart({ configFilePaths, rootPath, restart }) {
    if (0 === configFilePaths.length) return;
    const watcher = await createChokidar(configFilePaths, rootPath, {
        ignoreInitial: true,
        ignorePermissionErrors: true,
        usePolling: true,
        interval: 100
    });
    const onChange = async (filePath)=>{
        await watcher.close();
        if (isTTY() && !process.env.DEBUG) process.stdout.write('\x1B[H\x1B[2J');
        const filename = node_path.relative(rootPath, filePath);
        logger_logger.info(`restarting Rstest as ${logger_color.yellow(filename)} changed\n`);
        await restart();
    };
    watcher.on('add', onChange);
    watcher.on('change', onChange);
    watcher.on('unlink', onChange);
}
export { watchFilesForRestart };
